<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\ProfileExaminationDispositionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:issue-profile-examination-disposition',description:'Seal the exact Profile examination disposition')]
final class SenateIssueProfileExaminationDispositionCommand extends Command{public function __construct(private readonly ProfileExaminationDispositionService$s){parent::__construct();}protected function configure():void{$this->addArgument('opening-id',InputArgument::REQUIRED)->addArgument('lord-speaker-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->decide((string)$i->getArgument('opening-id'),(string)$i->getArgument('lord-speaker-binding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>PROFILE_EXAMINATION_DISPOSITION_SEALED</info> '.$r['disposition_id']);return self::SUCCESS;}}
